{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    if not nodes or not isinstance(nodes, list):
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(core, dict) or not all(n in core for n in nodes):
        raise ValueError("core_distance must cover all nodes")
    if not isinstance(dist_list, list):
        raise ValueError("distances must be a list")
    edge_set = set()
    edges = []
    for entry in dist_list:
        if len(entry) != 3:
            raise ValueError("each distance entry must have 3 elements")
        a, b, d = entry
        if a not in nodes or b not in nodes:
            raise ValueError(f"unknown node {a} or {b}")
        if a == b:
            continue
        if a > b:
            a, b = b, a
        key = (a, b)
        if key in edge_set:
            continue
        edge_set.add(key)
        weight = max(core[a], core[b], d)
        edges.append((a, b, weight))
    edges.sort(key=lambda x: (x[2], x[0], x[1]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for a, b, w in edges:
        if union(a, b):
            mst.append([a, b, w])
            total += w
            if len(mst) == len(nodes) - 1:
                break
    if len(mst) != len(nodes) - 1:
        raise ValueError("graph is disconnected; cannot form MST")
    return {"mst_edges": mst, "total_weight": total}"
}
